{
  "contract": "WAsgard",
  "closure": {
    "site_function": "wrap",
    "site_call": ".transferFrom",
    "functions": ["wrap"],
    "justification": "wrap is the function containing the risky call to .transferFrom, which may re-enter."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [],
    "nesting_bound": {}
  },
  "phases": {
    "function": "wrap",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before .transferFrom"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before .transferFrom",
      "to_marker": "after .transferFrom"
    },
    "post": {
      "name": "post",
      "from_marker": "after .transferFrom",
      "to_marker": "end"
    },
    "linearization_point": "after .transferFrom"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint",
      "meaning": "tokens being transferred during wrap call",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum__balances == _totalSupply + inFlight",
    "stable_formula": "_sum__balances == _totalSupply",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum__balances == _totalSupply",
    "rule": "The exposure invariant ensures that the sum of balances, accounting for in-flight transfers, equals total supply during reentrant calls."
  }
}
